import React from "react";
import { Navigate, useLocation } from "react-router-dom";
import { useAuth, AUTH_STATUS } from "../../context/auth.context";
import LoadingScreen from "../common/loading.screen.jsx";

/**
 * RequireAuth пускает дальше только авторизованного пользователя.
 *
 * Раньше guard'ов не было вообще: /dashboard и /create-set открывались без
 * входа, а данные просто не загружались.
 */
const RequireAuth = ({ children }) => {
    const { status } = useAuth();
    const location = useLocation();

    if (status === AUTH_STATUS.loading) {
        return <LoadingScreen />;
    }

    if (status !== AUTH_STATUS.authenticated) {
        // state.from позволяет вернуть пользователя туда, куда он шёл.
        return <Navigate to="/signin" state={{ from: location }} replace />;
    }

    return children;
};

export default RequireAuth;
