import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import authService from "../api/auth.service";
import { AUTH_EVENTS } from "../api/api";

export const AUTH_STATUS = {
    loading: "loading",
    authenticated: "authenticated",
    anonymous: "anonymous",
};

const AuthContext = createContext(null);

/**
 * AuthProvider держит состояние авторизации для всего приложения.
 *
 * Почему так: токены лежат в HttpOnly cookie и недоступны из JS, поэтому
 * единственный способ понять, авторизован ли пользователь, — спросить /auth/me.
 * Раньше состояние не хранилось вообще, и каждый экран решал это сам.
 */
export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [status, setStatus] = useState(AUTH_STATUS.loading);

    // Проверка сессии при загрузке приложения.
    useEffect(() => {
        let active = true;

        authService
            .me()
            .then((data) => {
                if (!active) return;
                setUser(data.user);
                setStatus(AUTH_STATUS.authenticated);
            })
            .catch(() => {
                if (!active) return;
                setUser(null);
                setStatus(AUTH_STATUS.anonymous);
            });

        return () => {
            active = false;
        };
    }, []);

    // Интерцептор axios сообщает, что продлить сессию не удалось.
    useEffect(() => {
        const handleUnauthorized = () => {
            setUser(null);
            setStatus(AUTH_STATUS.anonymous);
        };

        window.addEventListener(AUTH_EVENTS.unauthorized, handleUnauthorized);
        return () => window.removeEventListener(AUTH_EVENTS.unauthorized, handleUnauthorized);
    }, []);

    const login = useCallback(async (loginValue, password) => {
        const data = await authService.login(loginValue, password);
        setUser(data.user);
        setStatus(AUTH_STATUS.authenticated);
        return data.user;
    }, []);

    const register = useCallback(async (loginValue, email, password, passwordConfirm) => {
        const data = await authService.register(loginValue, email, password, passwordConfirm);
        return data.user;
    }, []);

    const logout = useCallback(async () => {
        try {
            await authService.logout();
        } catch (error) {
            // Даже если сервер недоступен, локально выходим из аккаунта.
        }
        setUser(null);
        setStatus(AUTH_STATUS.anonymous);
    }, []);

    const value = useMemo(
        () => ({
            user,
            status,
            isAuthenticated: status === AUTH_STATUS.authenticated,
            isLoading: status === AUTH_STATUS.loading,
            login,
            register,
            logout,
        }),
        [user, status, login, register, logout]
    );

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error("useAuth должен вызываться внутри AuthProvider");
    }
    return context;
};

export default AuthContext;
