import api from "./api";

// Токены больше не хранятся в localStorage: они приходят в HttpOnly cookie,
// поэтому методы setClient/getAccessToken удалены вместе с модулем token.jsx.
class AuthService {
    register(login, email, password, passwordConfirm) {
        return api
            .post("/auth/register", {
                login: login,
                email: email,
                password: password,
                password_confirm: passwordConfirm,
            })
            .then((response) => response.data);
    }

    // skipAuthRefresh: 401 на входе значит "неверные данные", а не "истёк токен".
    login(login, password) {
        return api
            .post("/auth/login", { login: login, password: password }, { skipAuthRefresh: true })
            .then((response) => response.data);
    }

    logout() {
        return api
            .post("/auth/logout", null, { skipAuthRefresh: true })
            .then((response) => response.data);
    }

    // Текущий пользователь. Идёт через интерцептор: если access-токен истёк,
    // он сначала попробует продлить сессию refresh-токеном.
    me() {
        return api.get("/auth/me").then((response) => response.data);
    }

    refresh() {
        return api
            .post("/auth/refresh", null, { skipAuthRefresh: true })
            .then((response) => response.data);
    }
}

const authService = new AuthService();

export default authService;
