import axios from "axios";

// Событие, на которое подписан AuthProvider: сессию продлить не удалось,
// пользователя нужно разлогинить.
export const AUTH_EVENTS = {
    unauthorized: "mindset:unauthorized",
};

// baseURL пустой: запросы идут на origin фронтенда, а CRA проксирует их на
// бэкенд (package.json → "proxy"). Благодаря этому HttpOnly cookie с токенами
// отправляются автоматически — они не уходят в cross-site запросах.
const instance = axios.create({
    baseURL: process.env.REACT_APP_BASE_API_URL || "",
    withCredentials: true,
    headers: {
        "Content-Type": "application/json",
    },
});

// Single-flight: если несколько запросов получили 401 одновременно, refresh
// уйдёт один раз, а остальные дождутся его результата.
let refreshPromise = null;

const refreshSession = () => {
    if (!refreshPromise) {
        refreshPromise = instance
            .post("/auth/refresh", null, { skipAuthRefresh: true })
            .finally(() => {
                refreshPromise = null;
            });
    }
    return refreshPromise;
};

instance.interceptors.response.use(
    (response) => response,
    async (error) => {
        const config = error.config || {};
        const status = error.response?.status;

        // skipAuthRefresh помечаются: /auth/login, /auth/logout, /auth/refresh.
        // Раньше сравнение шло по строке URL, и падающий refresh уходил в этот же
        // интерцептор повторно (потенциальная рекурсия).
        const canRetry = status === 401 && !config.skipAuthRefresh && !config._retried;

        if (canRetry) {
            config._retried = true;
            try {
                await refreshSession();
                // Токены лежат в cookie, поэтому повторяем исходный запрос как
                // есть — новый access-токен подставит браузер.
                return instance.request(config);
            } catch (refreshError) {
                window.dispatchEvent(new Event(AUTH_EVENTS.unauthorized));
                return Promise.reject(refreshError);
            }
        }

        return Promise.reject(error);
    }
);

export default instance;
